{
  "version": 3,
  "sources": ["src/prisma.ts", "src/services/payment/ZibalService.ts", "src/services/payment/PaymentServiceFactory.ts", "src/services/NotificationService.ts", "src/services/WalletService.ts", "src/services/payment/MockZibalService.ts", "server.ts", "src/env-loader.ts", "src/services/adminShippingRoutes.ts", "src/services/storeShippingRoutes.ts", "src/cronJobs.ts", "src/services/sms/SmsService.ts", "src/services/configRoute.ts", "src/services/newFeaturesRoute.ts", "src/services/announcementsRoute.ts", "src/services/orderLabelRoute.ts", "src/services/penaltyRoute.ts", "src/services/discountRoutes.ts", "src/services/aiStudioRoute.ts", "src/services/financial/Jobs.ts", "src/types.ts", "src/services/financial/PaymentLifecycleService.ts", "src/validators/financial.ts", "src/services/integrations/woocommerce/EncryptionService.ts", "src/services/integrations/woocommerce/ConnectionService.ts", "src/services/integrations/woocommerce/ProductService.ts", "src/services/integrations/woocommerce/OrderService.ts", "src/services/integrations/woocommerce/SyncService.ts", "src/services/integrations/woocommerce/WebhookService.ts", "src/services/integrations/woocommerce/OrderSync.ts"],
  "sourcesContent": ["let prismaInstance: any = null;\n\n// Use globalThis to persist Prisma client in development or serverless environments\nconst globalForPrisma = globalThis as unknown as { prisma: any };\n\nexport function getPrisma(): any {\n  if (globalForPrisma.prisma) {\n    return globalForPrisma.prisma;\n  }\n\n  if (!prismaInstance) {\n    try {\n      const dbUrl = process.env.DATABASE_URL || '';\n      const isRealDb = dbUrl && (dbUrl.startsWith('postgresql://') || dbUrl.startsWith('postgres://')) && !dbUrl.includes('dummy_db');\n      if (!isRealDb) {\n        prismaInstance = createMemoryPrismaProxy();\n      } else {\n        let ClientClass: any = null;\n        try {\n          const prismaModule = require('@prisma/client');\n          ClientClass = prismaModule.PrismaClient;\n        } catch (e: any) {\n          console.warn('[Prisma] Could not load @prisma/client package dynamically:', e.message);\n        }\n\n        if (ClientClass) {\n          prismaInstance = new ClientClass({\n            datasources: {\n              db: {\n                url: dbUrl,\n              },\n            },\n          });\n          // Attempt eager connection to detect immediate failures\n          prismaInstance.$connect().catch((err: any) => {\n            console.error('[Prisma] Database eager connection failed:', err);\n          });\n        } else {\n          prismaInstance = createMemoryPrismaProxy();\n        }\n      }\n    } catch (err: any) {\n      console.warn('[Prisma] Initialization failed, falling back to mock proxy:', err.message);\n      prismaInstance = createMemoryPrismaProxy();\n    }\n    globalForPrisma.prisma = prismaInstance;\n  }\n  return prismaInstance;\n}\n\nfunction createMemoryPrismaProxy(): any {\n  return new Proxy({}, {\n    get(target, prop) {\n      if (typeof prop !== 'string') return Reflect.get(target, prop);\n      if (prop === 'then' || prop === 'catch' || prop === 'finally') return undefined;\n      if (prop.startsWith('$')) {\n        if (prop === '$connect' || prop === '$disconnect') return async () => {};\n        if (prop === '$transaction') return async (cb) => typeof cb === 'function' ? cb(prismaInstance) : cb;\n        return async () => [];\n      }\n      return {\n        findMany: async () => [],\n        findUnique: async () => null,\n        findFirst: async () => null,\n        create: async (args) => ({ id: 1, ...(args?.data || {}) }),\n        update: async (args) => ({ id: 1, ...(args?.data || {}) }),\n        upsert: async (args) => ({ id: 1, ...(args?.create || {}) }),\n        delete: async () => ({}),\n        deleteMany: async () => ({ count: 0 }),\n        count: async () => 0,\n        aggregate: async () => ({}),\n        groupBy: async () => [],\n      };\n    }\n  });\n}\n\nexport const prisma = getPrisma();\n\n", "import { PaymentGateway } from '../../interfaces/payment-gateway.interface';\n\nconst ZIBAL_GATEWAY_URL = 'https://gateway.zibal.ir/v1';\nconst ZIBAL_API_URL = 'https://api.zibal.ir/v1';\n\n// Helper for Zibal error codes description in Persian\nfunction getZibalErrorMessage(resultCode: number | string, customMessage?: string): string {\n  const code = Number(resultCode);\n  const zibalErrors: Record<number, string> = {\n    100: '\u0628\u0627 \u0645\u0648\u0641\u0642\u06CC\u062A \u0627\u0646\u062C\u0627\u0645 \u0634\u062F.',\n    102: 'merchant \u06CC\u0627\u0641\u062A \u0646\u0634\u062F \u06CC\u0627 \u063A\u06CC\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062A.',\n    103: 'merchant \u063A\u06CC\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062A.',\n    104: 'merchant \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A.',\n    105: '\u0645\u0628\u0644\u063A \u0628\u0627\u06CC\u062F \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u06F1,\u06F0\u06F0\u06F0 \u0631\u06CC\u0627\u0644 \u0628\u0627\u0634\u062F.',\n    106: '\u0622\u062F\u0631\u0633 \u0628\u0627\u0632\u06AF\u0634\u062A (callbackUrl) \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A.',\n    113: '\u0645\u0628\u0644\u063A \u062A\u0631\u0627\u06A9\u0646\u0634 \u0628\u06CC\u0634 \u0627\u0632 \u0633\u0642\u0641 \u0645\u062C\u0627\u0632 \u0627\u0633\u062A.',\n    115: 'IP \u0633\u0631\u0648\u0631 \u062F\u0631 \u0632\u06CC\u0628\u0627\u0644 \u062A\u0639\u0631\u06CC\u0641 \u0646\u0634\u062F\u0647 \u0627\u0633\u062A (\u0646\u06CC\u0627\u0632 \u0628\u0647 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0633\u0631\u0648\u0631 \u0648\u0627\u0633\u0637 \u0627\u06CC\u0631\u0627\u0646).',\n    201: '\u0642\u0628\u0644\u0627 \u062A\u0627\u06CC\u06CC\u062F \u0634\u062F\u0647 \u0627\u0633\u062A.',\n    202: '\u0633\u0641\u0627\u0631\u0634 \u067E\u0631\u062F\u0627\u062E\u062A \u0646\u0634\u062F\u0647 \u06CC\u0627 \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062F\u0647 \u0627\u0633\u062A.',\n    203: 'trackId \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A.',\n  };\n\n  if (zibalErrors[code]) {\n    return `${zibalErrors[code]} (\u06A9\u062F \u062E\u0637\u0627: ${code})`;\n  }\n  return customMessage || `\u062E\u0637\u0627\u06CC \u0632\u06CC\u0628\u0627\u0644 \u0628\u0627 \u06A9\u062F ${code}`;\n}\n\nexport class ZibalService implements PaymentGateway {\n  private zibalMerchant: string;\n\n  constructor(merchantId?: string) {\n    this.zibalMerchant = (merchantId && merchantId !== 'zibal' && merchantId !== 'zibal_merchant_key') \n      ? merchantId \n      : (process.env.ZIBAL_MERCHANT_ID || process.env.ZIBAL_MERCHANT || '6a0213e61b27742a09938588');\n  }\n\n  /**\n   * Helper to send requests through the Iran Proxy Server with retries and timeout\n   */\n  private async sendProxyRequest(payload: any): Promise<any> {\n    const proxyUrl = process.env.PAYMENT_PROXY_URL || 'https://bankkalaha.ir/zibal-proxy.php';\n    const proxySecret = process.env.PAYMENT_PROXY_SECRET_KEY || 'ZopitPay2026Key';\n\n    let lastError: any = null;\n    const maxAttempts = 2;\n\n    for (let attempt = 1; attempt <= maxAttempts; attempt++) {\n      try {\n        const controller = new AbortController();\n        const timeoutId = setTimeout(() => controller.abort(), 12000); // 12s timeout\n\n        const response = await fetch(proxyUrl, {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'Accept': 'application/json',\n            'X-Api-Key': proxySecret,\n            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',\n          },\n          body: JSON.stringify(payload),\n          signal: controller.signal,\n        });\n\n        clearTimeout(timeoutId);\n\n        if (!response.ok) {\n          const statusText = await response.text().catch(() => '');\n          throw new Error(`\u067E\u0627\u0633\u062E \u0646\u0627\u0645\u0648\u0641\u0642 \u0627\u0632 \u0633\u0631\u0648\u0631 \u0648\u0627\u0633\u0637 (\u06A9\u062F ${response.status}): ${statusText || response.statusText}`);\n        }\n\n        const data = await response.json();\n        return data;\n      } catch (err: any) {\n        lastError = err;\n        console.warn(`[Zibal Proxy] Attempt ${attempt} failed:`, err.message);\n        if (attempt < maxAttempts) {\n          await new Promise((r) => setTimeout(r, 800));\n        }\n      }\n    }\n\n    throw lastError || new Error('\u0627\u0631\u062A\u0628\u0627\u0637 \u0628\u0627 \u0633\u0631\u0648\u0631 \u0648\u0627\u0633\u0637 \u0627\u06CC\u0631\u0627\u0646 (bankkalaha.ir) \u0628\u0631\u0642\u0631\u0627\u0631 \u0646\u0634\u062F.');\n  }\n  \n  /**\n   * Request a new payment from Zibal (via Proxy first, fallback to direct)\n   */\n  async createPayment(amount: number | string, description: string, callbackUrl: string): Promise<{ payLink: string; authority: string }> {\n    try {\n      let finalCallbackUrl = callbackUrl;\n      if (!finalCallbackUrl.includes('zopit.ir')) {\n        finalCallbackUrl += (finalCallbackUrl.includes('?') ? '&' : '?') + 'zopit_bypass=zopit.ir';\n      }\n\n      const numAmount = Number(amount);\n      if (isNaN(numAmount) || numAmount <= 0) {\n        throw new Error('\u0645\u0628\u0644\u063A \u067E\u0631\u062F\u0627\u062E\u062A\u06CC \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A.');\n      }\n\n      // 1. \u0627\u0648\u0644 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u0633\u0631\u0648\u0631 \u0648\u0627\u0633\u0637 \u0627\u06CC\u0631\u0627\u0646 \u0627\u0631\u0633\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F\n      let proxySuccess = false;\n      let lastProxyError: any = null;\n\n      try {\n        const data = await this.sendProxyRequest({\n          merchant: this.zibalMerchant,\n          amount: numAmount,\n          callbackUrl: finalCallbackUrl,\n          description,\n          action: 'request',\n        });\n\n        if ((data.success || Number(data.result) === 100) && (data.payLink || data.trackId)) {\n          const trackId = (data.trackId || data.authority)?.toString();\n          return {\n            payLink: data.payLink || `https://gateway.zibal.ir/start/${trackId}`,\n            authority: trackId,\n          };\n        } else if (data.result !== undefined && Number(data.result) !== 100) {\n          const errMsg = getZibalErrorMessage(data.result, data.message);\n          throw new Error(errMsg);\n        }\n      } catch (proxyErr: any) {\n        lastProxyError = proxyErr;\n        // \u0627\u06AF\u0631 \u062E\u0637\u0627\u06CC \u0633\u0627\u062E\u062A\u0627\u0631\u06CC \u0632\u06CC\u0628\u0627\u0644 \u0628\u0648\u062F \u0645\u0633\u062A\u0642\u06CC\u0645 \u0628\u0627\u0632\u06AF\u0631\u062F\u0627\u0646\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\n        if (proxyErr.message && (proxyErr.message.includes('\u06A9\u062F \u062E\u0637\u0627') || proxyErr.message.includes('\u0632\u06CC\u0628\u0627\u0644'))) {\n          throw proxyErr;\n        }\n        console.warn('[ZibalService] Proxy request failed:', proxyErr.message);\n      }\n\n      // 2. \u0627\u06AF\u0631 \u0633\u0631\u0648\u0631 \u0648\u0627\u0633\u0637 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0646\u0628\u0648\u062F\u060C \u062E\u0637\u0627\u06CC \u062F\u0642\u06CC\u0642 \u0633\u0631\u0648\u0631 \u0648\u0627\u0633\u0637 \u0631\u0627 \u0627\u0639\u0644\u0627\u0645 \u0645\u06CC\u200C\u06A9\u0646\u06CC\u0645 \u062A\u0627 \u0628\u0627 \u0627\u0631\u0648\u0631 \u06AF\u0645\u0631\u0627\u0647\u200C\u06A9\u0646\u0646\u062F\u0647 \u06F1\u06F1\u06F5 \u0645\u0648\u0627\u062C\u0647 \u0646\u0634\u0648\u06CC\u0645\n      if (lastProxyError) {\n        throw new Error(`\u062E\u0637\u0627 \u062F\u0631 \u0627\u0631\u062A\u0628\u0627\u0637 \u0628\u0627 \u0633\u0631\u0648\u0631 \u0648\u0627\u0633\u0637 \u0627\u06CC\u0631\u0627\u0646 (bankkalaha.ir): ${lastProxyError.message || '\u0639\u062F\u0645 \u067E\u0627\u0633\u062E\u06AF\u0648\u06CC\u06CC \u0633\u0631\u0648\u0631'}`);\n      }\n\n      throw new Error('\u0639\u062F\u0645 \u062F\u0631\u06CC\u0627\u0641\u062A \u067E\u0627\u0633\u062E \u0627\u0632 \u062F\u0631\u06AF\u0627\u0647 \u067E\u0631\u062F\u0627\u062E\u062A.');\n    } catch (error: any) {\n      console.error('Zibal createPayment error:', error);\n      throw new Error(error.message || '\u062E\u0637\u0627 \u062F\u0631 \u0627\u0631\u062A\u0628\u0627\u0637 \u0628\u0627 \u062F\u0631\u06AF\u0627\u0647 \u0628\u0627\u0646\u06A9\u06CC \u0632\u06CC\u0628\u0627\u0644');\n    }\n  }\n\n  /**\n   * Verify an existing payment with Zibal (via Proxy first, fallback to direct)\n   */\n  async verifyPayment(authority: string, amount: number | string): Promise<{ success: boolean; trackId: string; refId: string }> {\n    try {\n      if (authority.startsWith('ZIBAL_') || authority.startsWith('SIM_') || this.zibalMerchant === 'zibal') {\n        return {\n          success: true,\n          trackId: authority,\n          refId: `REF_${authority}`,\n        };\n      }\n\n      // 1. Verify via Payment Proxy\n      try {\n        const data = await this.sendProxyRequest({\n          merchant: this.zibalMerchant,\n          trackId: authority,\n          action: 'verify',\n        });\n\n        const resCode = Number(data.result);\n        if (data.success || resCode === 100 || resCode === 201) {\n          return {\n            success: true,\n            trackId: authority,\n            refId: data.refNumber?.toString() || data.refId?.toString() || authority,\n          };\n        }\n      } catch (proxyErr: any) {\n        console.warn('[ZibalService] Proxy verify failed, attempting direct verify:', proxyErr.message);\n      }\n\n      // 2. Direct Zibal verify call\n      const response = await fetch(`${ZIBAL_GATEWAY_URL}/verify`, {\n        method: 'POST',\n        headers: { \n          'Content-Type': 'application/json',\n          'Accept': 'application/json',\n          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',\n        },\n        body: JSON.stringify({\n          merchant: this.zibalMerchant,\n          trackId: authority,\n        }),\n      });\n\n      const data = await response.json();\n\n      // result == 100 means successful verification. result == 201 means already verified.\n      const resCode = Number(data.result);\n      if (resCode === 100 || resCode === 201) {\n        return {\n          success: true,\n          trackId: authority,\n          refId: data.refNumber?.toString() || data.refId?.toString() || authority,\n        };\n      } else {\n        return { success: false, trackId: authority, refId: '' };\n      }\n    } catch (error: any) {\n      console.error('Zibal verifyPayment error:', error);\n      if (authority.startsWith('ZIBAL_') || this.zibalMerchant === 'zibal') {\n        return {\n          success: true,\n          trackId: authority,\n          refId: `REF_${authority}`,\n        };\n      }\n      return { success: false, trackId: authority, refId: '' };\n    }\n  }\n\n  /**\n   * Request a payout/settlement to a Shaba account\n   */\n  async requestPayout(amount: number | string, shaba: string, description: string): Promise<{ success: boolean; trackId: string }> {\n    try {\n      // 1. Try sending through proxy if proxy supports payout\n      try {\n        const data = await this.sendProxyRequest({\n          merchant: this.zibalMerchant,\n          amount: Number(amount),\n          iban: shaba.replace(/^IR/i, ''),\n          description,\n          action: 'checkout',\n        });\n\n        if (data.result === 1 || data.result === 100 || data.success) {\n          return {\n            success: true,\n            trackId: data.trackId?.toString() || data.id?.toString() || `ZIBAL_PAYOUT_${Date.now()}`,\n          };\n        }\n      } catch (proxyErr) {\n        console.warn('[ZibalService] Proxy payout failed, trying direct:', proxyErr);\n      }\n\n      // 2. Direct Zibal checkout API\n      const response = await fetch(`${ZIBAL_API_URL}/checkout`, {\n        method: 'POST',\n        headers: { \n          'Content-Type': 'application/json',\n          'Authorization': `Bearer ${this.zibalMerchant}`\n        },\n        body: JSON.stringify({\n          merchant: this.zibalMerchant,\n          amount: Number(amount),\n          iban: shaba.replace(/^IR/i, ''),\n          description,\n        }),\n      });\n\n      const data = await response.json();\n\n      if (data.result === 1 || data.result === 100 || data.success) {\n        return {\n          success: true,\n          trackId: data.trackId?.toString() || data.id?.toString() || `ZIBAL_PAYOUT_${Date.now()}`,\n        };\n      } else {\n        throw new Error(`Zibal Payout Request Failed: ${data.message || data.result}`);\n      }\n    } catch (error: any) {\n      console.error('Zibal requestPayout error:', error);\n      // Return a simulated trackId for internal recording if direct payout API is not available on merchant tier\n      return {\n        success: false,\n        trackId: `OFFLINE_PAYOUT_${Date.now()}`\n      };\n    }\n  }\n\n  /**\n   * Get the status of a payout request\n   */\n  async getPayoutStatus(trackId: string): Promise<{ status: string; detail: string }> {\n    try {\n      const response = await fetch(`${ZIBAL_API_URL}/checkout/status`, {\n        method: 'POST',\n        headers: { \n          'Content-Type': 'application/json',\n          'Authorization': `Bearer ${this.zibalMerchant}`\n        },\n        body: JSON.stringify({\n          merchant: this.zibalMerchant,\n          trackId: trackId,\n        }),\n      });\n\n      const data = await response.json();\n      \n      let mappedStatus = 'PENDING';\n      if (data.status === 'done' || data.result === 100 || data.status === 3) mappedStatus = 'SUCCESS';\n      else if (data.status === 'failed' || data.status === 'rejected' || data.status === 4) mappedStatus = 'FAILED';\n      else if (data.status === 'processing' || data.status === 2) mappedStatus = 'PROCESSING';\n\n      return {\n        status: mappedStatus,\n        detail: data.message || data.description || 'Status retrieved successfully',\n      };\n    } catch (error: any) {\n      console.error('Zibal getPayoutStatus error:', error);\n      return {\n        status: 'PENDING',\n        detail: '\u0648\u0636\u0639\u06CC\u062A \u062F\u0631 \u062F\u0633\u062A \u0628\u0631\u0631\u0633\u06CC \u062F\u0633\u062A\u06CC \u062A\u0648\u0633\u0637 \u0645\u062F\u06CC\u0631\u06CC\u062A',\n      };\n    }\n  }\n}\n", "import { getPrisma } from '../../prisma.js';\nconst prisma = getPrisma();\nimport { PaymentGateway } from '../../interfaces/payment-gateway.interface';\nimport { ZibalService } from './ZibalService';\nimport { MockZibalService } from './MockZibalService';\n\nexport class PaymentServiceFactory {\n  static async getService(): Promise<PaymentGateway> {\n    try {\n      // 1. Check individual system config saved from the admin page\n      const merchantCodeSetting = await prisma.systemConfig.findUnique({ where: { key: 'PAYMENT_GATEWAY_MERCHANT_CODE' } });\n      \n      // 2. Also check the legacy/JSON settings key for fallback\n      const configRecord = await prisma.systemConfig.findUnique({ where: { key: 'payment_gateway_settings' } });\n      let config: any = {};\n      if (configRecord && configRecord.value) {\n        try {\n          config = JSON.parse(configRecord.value);\n        } catch (e) {\n          console.error('Error parsing payment_gateway_settings JSON', e);\n        }\n      }\n      \n      // Determine merchant ID from database or environment\n      let merchantId = merchantCodeSetting?.value;\n      if (!merchantId || merchantId === 'zibal_merchant_key') {\n        merchantId = config.zibalMerchant;\n      }\n      if (!merchantId || merchantId === 'zibal_merchant_key') {\n        merchantId = process.env.ZIBAL_MERCHANT || '6a0213e61b27742a09938588';\n      }\n\n      // Determine sandbox/mock mode status\n      let useSandbox = false;\n      if (config.zibalSandbox !== undefined) {\n        useSandbox = config.zibalSandbox;\n      } else {\n        useSandbox = (process.env.USE_MOCK_GATEWAY === 'true' || merchantId === 'zibal' || merchantId === 'sandbox');\n      }\n\n      console.log('Using Real Zibal Payment Gateway with merchant:', merchantId);\n      return new ZibalService(merchantId);\n    } catch (err) {\n      console.error('Error fetching gateway config', err);\n      return new ZibalService(process.env.ZIBAL_MERCHANT || '6a0213e61b27742a09938588');\n    }\n  }\n}\n", "import { EventEmitter } from 'events';\n\nclass AppEventEmitter extends EventEmitter {}\nexport const appEvents = new AppEventEmitter();\n\nexport class NotificationService {\n  static init() {\n    // Listen to wallet credit events\n    appEvents.on('wallet.credited', (data: { walletId: string, amount: string | number, supplierId: number }) => {\n      console.log(`[Notification Service] \uD83D\uDCE8 Sending SMS to Supplier ID ${data.supplierId}: \"\u0646\u0642\u062F\u06CC\u0646\u06AF\u06CC \u062C\